from dataclasses import dataclass
from typing import Annotated

@dataclass
class Patient:
    id: str
    ssn: str
    dob: str

def serialize(classifier: PiiClassification, p: Patient, audience: str) -> dict:
    return dict(classifier.mask(p, audience=audience))

from datetime import datetime, timezone

def on_anomaly(queue: BreachNotificationQueue, evidence: str) -> str:
    now = datetime.now(timezone.utc)
    return queue.open_incident(detected_at=now, severity='high', summary=evidence)
